<div class="booking-service-card" data-booking-service="{{ $service->id }}" data-requires-full-day="{{ $service->requires_full_day ? 'true' : 'false' }}" data-requires-operation-consent="{{ $service->requires_operation_consent ? 'true' : 'false' }}" data-requires-bore-up-package="{{ $service->requires_bore_up_package ? 'true' : 'false' }}">
    <label class="booking-choice" data-quote-service data-quote-label="{{ $service->name }}" data-pricing-mode="{{ $service->labor_pricing_mode }}" data-labor-category="{{ $service->labor_category }}" data-labor-group="{{ $service->labor_group }}" data-shared-operation-minutes="{{ $service->shared_operation_minutes ?? 0 }}" data-unit-price="{{ $service->estimated_labor_price_rupiah ?? '' }}" data-duration="{{ $service->duration_minutes ?? 0 }}"><input type="checkbox" name="service_ids[]" value="{{ $service->id }}" @checked(in_array($service->id, is_array(old('service_ids')) ? old('service_ids') : $prefilledServiceIds))><img class="booking-service-thumb" src="{{ $service->image_url ?: asset('images/service-mechanic.jpg') }}" alt="" loading="lazy"><span><strong>{{ $service->name }}</strong><small>{{ $service->summary }} · {{ $service->requires_full_day ? 'One full workshop day' : ($service->duration_minutes ? $service->duration_minutes.' min standard estimate' : 'Duration confirmed by workshop') }}</small></span><b>{{ $service->labor_pricing_mode === 'time_based' ? 'Fixed estimate from standard duration' : ($service->estimated_labor_price_rupiah !== null ? 'Rp '.number_format($service->estimated_labor_price_rupiah, 0, ',', '.') : 'Price requires workshop confirmation') }}</b></label>
    @if($service->partVariants->isNotEmpty())<div class="service-part-selection" data-service-part-selection hidden><span class="eyebrow">PART OPTIONS FOR {{ strtoupper($service->name) }}</span><p class="field-help">These options are attached to this workshop service. Unverified fitment is checked by the mechanic.</p>
        @foreach($service->partVariants as $variant)
            @php($partPrice = $variant->selling_price_rupiah ?? $variant->part->selling_price_rupiah)
