            @php($partLabel = $variant->pivot->component_label ?: $variant->part->name)
            <label class="service-part-choice" data-quote-part data-required="{{ $isRequired ? 'true' : 'false' }}" data-service-id="{{ $service->id }}" data-quote-label="{{ $partLabel.' — '.$variant->part->name.' '.$variant->name }}" data-unit-price="{{ $partPrice ?? '' }}" data-quantity="{{ $variant->pivot->quantity }}" data-duration="{{ $variant->pivot->duration_minutes ?? 0 }}">
                @if(!$isRequired)<input type="checkbox" name="service_part_variant_ids[{{ $service->id }}][]" value="{{ $variant->id }}" @checked(in_array($variant->id, old('service_part_variant_ids.'.$service->id, [])))>@else<span class="required-part-mark">Included</span>@endif
                <span><strong>{{ $partLabel }} / {{ $variant->part->name }} — {{ $variant->name }}</strong><small>{{ $variant->part->brand?->name ?? 'Unbranded' }} · SKU {{ $variant->sku ?: $variant->part->sku ?: 'not set' }} · Qty {{ $variant->pivot->quantity }}@foreach($variant->attributeValues as $attribute) · {{ $attribute->attribute->name }} {{ $attribute->value }}{{ $attribute->attribute->unit ? ' '.$attribute->attribute->unit : '' }}@endforeach</small><em>Fitment is checked against your selected motorcycle; unverified options require mechanic confirmation.</em></span>
                <b>{{ $partPrice !== null ? 'Rp '.number_format($partPrice, 0, ',', '.') : 'Price requires workshop confirmation' }}</b>
